SELECT Country, AVG(Total) AS AverageInvoiceTotal
FROM Invoice
GROUP BY Country;

SELECT income_group, COUNT(*) AS num_countries
FROM countries
GROUP BY income_group;

SELECT AVG(life_expectancy_years) AS population_weighted_average_life_expectancy
FROM country_stats
WHERE year = 2023;

SELECT country_stats.gdp_per_capita_usd, country_stats.life_expectancy_years, country_stats.fertility_rate, country_stats.population, country_stats.gdp_usd, country_stats.unemployment_pct
FROM country_stats
WHERE year = 2023;
